 expected_before jsonb := $before$[{"id":"R-105-2-12","law":"","qno":"12","year":"105","major":"研究倫理","opt_a":"C. Das, M. E. Kondrat, C. M. Lam, and L. S. Shulman","opt_b":"Chatili Das, Mary Ellen Kondrat, Ching Man Lam, Lee S. Shulman","opt_c":"Das, C., Kondrat, M. E., Lam, C. M., and Shulman, L. S.","opt_d":"Chatili, D., Mary, E. K., Ching, M. L., and Lee, S. S. 情況：假想廖教授計劃以臺灣社會工作專業人員協會的所有會員進行普查。研究者所擬定的其中 一個研究假設為「女性社工人員的倫理兩難決斷力較男性來得高」。請依上述資料回答下 列第題至第題。","round":"第二次","topic":"學術倫理 > APA引用格式","answer":"C","exp_raw":"","exp_why":"(C)正確：APA格式引用＝『姓氏在前、名字縮寫在後』——Das, C., Kondrat, M. E., Lam, C. M., and Shulman, L. S.。","mistake":"關鍵字漏看","subject":"社會工作研究方法","exp_trap":"APA引用＝姓氏, 名縮寫.(Das, C.);多作者依序列出。","keywords":"APA格式, 文獻引用","mnemonic":"APA引用格式＝姓氏在前、名字縮寫(Das, C.)。","question":"某社工人員在撰寫有關課後照顧的評估報告時，參考了一篇由 Chatili Das、Mary Ellen Kondrat、Ching Man Lam、Lee S. Shulman四位作者所共同撰寫的文章。依 APA 格式，在此評估報告的「參考文獻」中，這篇文獻作者的寫法應該是：","extension":"學術倫理(APA引用)。","exp_others":"(A)名縮寫在前姓在後(順序反)、(B)全名未縮寫、(D)把名當姓切割。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-13","law":"","qno":"13","year":"105","major":"研究邏輯","opt_a":"問題型","opt_b":"宣示型","opt_c":"概念型","opt_d":"虛無型","round":"第二次","topic":"研究假設 > 假設類型","answer":"B","exp_raw":"","exp_why":"(B)宣示型(陳述型)假設：直接『宣示』變項間的預期關係(肯定句陳述)，相對於問題型(疑問句)與虛無型(無差異)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"宣示型(肯定陳述)/問題型(疑問)/虛無型(無差異)。","keywords":"宣示型假設, 問題型, 虛無型","mnemonic":"假設類型:宣示型(肯定陳述)/問題型(疑問)/虛無型(無差異)。","question":"以上說明是屬於那一種研究假設？","extension":"研究假設(假設類型)。","exp_others":"(A)問題型以疑問句呈現、(C)概念型非假設類型用語、(D)虛無型陳述『無差異/無關係』。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-14","law":"","qno":"14","year":"105","major":"變項","opt_a":"自變項為女性；依變項為倫理兩難決斷力","opt_b":"自變項為倫理兩難決斷力；依變項為性別","opt_c":"自變項為倫理兩難決斷力；依變項為男性","opt_d":"自變項為性別；依變項為倫理兩難決斷力","round":"第二次","topic":"變項 > 自變項依變項辨識","answer":"D","exp_raw":"","exp_why":"假設「性別→倫理兩難決斷力」中,自變項為性別、依變項為倫理兩難決斷力;(D)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"自變項=拿來分組/解釋的(性別);依變項=被影響的(決斷力)。","keywords":"自變項, 依變項, 性別倫理決斷","mnemonic":"自變項=性別;依變項=倫理兩難決斷力。","question":"這個研究假設的自變項與依變項為何？","extension":"變項;自變依變項。","exp_others":"(A)(B)(C)把自變依變項對調或配錯——性別是「原因」、決斷力是「被影響的結果」。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-15","law":"","qno":"15","year":"105","major":"統計檢定","opt_a":"多因子變異數分析","opt_b":"簡單迴歸分析","opt_c":"卡方檢定","opt_d":"獨立樣本 t 檢定","round":"第二次","topic":"統計檢定 > 獨立樣本t","answer":"D","exp_raw":"","exp_why":"依題意是用連續的量表總分、比較兩組人在「倫理決斷力」上的平均高低，而且不改變測量層次（分數維持連續）。連續分數、兩組比平均＝獨立樣本 t 檢定。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"維持連續分數比兩組平均＝獨立 t；若把分數硬切成高/低類別才會變卡方。","keywords":"獨立樣本t, 性別比較","mnemonic":"連續分數、兩組比平均＝獨立 t。","question":"若廖教授以其自行設計的 10 題五等尺度量表來測量社工人員的「倫理決斷能力」，得 分越高代表倫理兩難決斷力越高。若研究者想驗證其所提出的這個研究假設，在不改變 變項測量層次的情形下，這位研究者應選用下列那個統計程序？","extension":"測量層次決定方法：連續→t／F、類別→卡方。","exp_others":"(A)多因子變異數分析需多個類別自變項；(B)簡單迴歸用連續變項預測；(C)卡方用於類別資料。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-16","law":"","qno":"16","year":"105","major":"信效度","opt_a":"鑑別度（discrimination）","opt_b":"效度（validity）","opt_c":"信度（reliability）","opt_d":"精確度（precision）","round":"第二次","topic":"信效度 > 效度質疑","answer":"B","exp_raw":"","exp_why":"(B)效度：男性社工質疑量表題目(頻率/時間/影響人數)對男性不利、未真正測到『決斷力』——質疑的是測量是否正確反映概念＝效度。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"質疑『測的不是那個概念』＝效度問題。","keywords":"效度, 量表代表性, 構念效度","mnemonic":"信度與效度關係:信度＝一致性穩定性(再測/複本/折半=內部一致性/評分者間=等同性;Cronbach's α);效度＝正確測到欲測概念(因素分析呼應理論=建構效度);有效度必有信度、有信度未必有效度;信度是效度的『必要非充分』條件;提高效度會帶來信度提高;『信度低效度高』不可能。","question":"若廖教授完成資料分析後，驗證了其所提出的「女性社工人員的倫理兩難決斷力較男性 來得高」這個研究假設。但有不少男性社工人員質疑量表中將進行倫理決策的頻率、時 間及影響人數等題目納入，忽略了男性社工人員比較少有機會從事第一線的實務工作， 因而較少參與在倫理兩難的決策中。請問這些男性社工人員質疑的是這個量表的：","extension":"信效度(效度爭議)。","exp_others":"(A)鑑別度是題目區分高低分組的能力、(C)信度是穩定性、(D)精確度非此爭點。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-20","law":"","qno":"20","year":"105","major":"抽樣","opt_a":"回收率通常會很低","opt_b":"樣本代表性不足","opt_c":"作答者會相互影響","opt_d":"樣本數經常會不足 情況：假想某政府單位委託民間民意調查機構，以電腦隨機撥號的方式，進行「臺灣應否逐步廢 除死刑以符合國際人權公約的準則」之電話民調。該調查指稱有效樣本數為 3,757 份，具 有 95%的信賴水準（confidence level）。請依上述資料回答下列第題至第題。","round":"第二次","topic":"抽樣 > 方便抽樣缺點","answer":"B","exp_raw":"","exp_why":"方便(便利)抽樣最大的缺點是「樣本代表性不足」(隨手取樣、偏誤大);(B)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"方便抽樣=「抓得到誰就用誰」,樣本偏、代表性最差。","keywords":"方便抽樣, 代表性不足, 偶遇","mnemonic":"方便抽樣最大缺點=樣本代表性不足。","question":"從抽樣的理論來看，方便抽樣（convenience sampling）昀大的缺點在於：","extension":"抽樣;方便抽樣。","exp_others":"(A)回收率低、(C)作答互相影響、(D)樣本數不足——皆非方便抽樣「最核心」的缺點。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-21","law":"","qno":"21","year":"105","major":"抽樣","opt_a":"樣本數不變，修改問卷內容，使題意更淺顯易懂","opt_b":"樣本數不變，改採分層隨機抽樣進行抽樣，以增加樣本代表性","opt_c":"增加有效樣本數到 10,500 人","opt_d":"針對同樣的樣本改採面訪，以減少電話訪問的機構效應","round":"第二次","topic":"抽樣 > 信賴水準與樣本數","answer":"C","exp_raw":"","exp_why":"(C)增加有效樣本數到10,500人：要把信賴水準提高到99%、又維持精準度，必須『大幅增加有效樣本數』。","mistake":"計算邏輯錯誤","subject":"社會工作研究方法","exp_trap":"信賴水準95%→99%＝樣本數須大幅增加(精度成本)。","keywords":"信賴水準, 99%, 樣本數計算","mnemonic":"提高信賴水準(99%)＝增加有效樣本數。","question":"若該民調想更精準地掌握民意，希望達到 99%的信賴水準，請問該民調公司該怎麼做？","extension":"抽樣(信賴水準與樣本數)。","exp_others":"(A)修改題意是測量品質問題、(B)樣本數不變只改抽法無法達成99%、(D)改面訪是調查方式問題——皆無法直接提升信賴水準。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-22","law":"","qno":"22","year":"105","major":"研究設計","opt_a":"歷史（history）","opt_b":"選取（selection）","opt_c":"成熟（maturation）","opt_d":"統計迴歸（statistical regression）","round":"第二次","topic":"研究設計 > 歷史效應","answer":"A","exp_raw":"","exp_why":"(A)歷史(history)：調查前發生隨機殺人事件並被大幅報導——研究期間的『外部事件』影響結果。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"內在效度威脅:歷史(研究期間外部事件影響)、成熟(隨時間自然變化)、測驗效應(前測影響後測)、工具(測量工具改變)、統計迴歸(選極端個案→自然回歸平均,高估或低估效果)、選樣(分組不隨機/自由選組→兩組原本不同質)、耗損(流失)、因果時序模糊。","keywords":"歷史效應, 外部事件, 內在效度威脅","mnemonic":"內在效度威脅:歷史/成熟/測驗/工具/統計迴歸/選樣/耗損/時序;「歷史」＝研究期間發生的外部事件。","question":"若在調查前幾天，剛好發生街頭隨機殺人事件，且經媒體大幅報導；顯然此街頭隨機殺 人事件及其後續的討論可能會影響民意調查的結果。請問影響該民意調查效度的因素為 何？","extension":"研究設計(歷史效應)。","exp_others":"(B)選取是分組不同質、(C)成熟是自然變化、(D)統計迴歸是極端回歸。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-107-2-04","law":"","qno":"4","year":"107","major":"研究設計","opt_a":"依變項置於圖的右邊，自變項置於左邊，單向箭頭的線條表示兩端的變項有因果關係，起 點的變項為因，終點箭頭指向的變項為果","opt_b":"單向箭頭的線條表示兩端的變項有因果關係，起點的變項為因，終點箭頭指向的變項為果","opt_c":"雙向箭頭的線條表示兩端的變項相關","opt_d":"沒有箭頭的線條表示兩端的變項沒有關係 情況：睡眠對健康至關重要。但研究發現，多數大學生睡眠品質不佳。葉教授想了解影響大學生 睡眠品質的因素，他從自己任教的大學裡，以系級名單隨機抽取 20 個班級，到這些班級發 放問卷，請全班同學填寫。問卷中，睡眠品質以「匹茲堡睡眠品質量表」（是由 7 題，每 題 4 點尺度的李克特（Likert）量表所構成，分數越高代表睡眠品質越差）來測量，其他變 項包括受訪者性別、每週運動時數、每天上網時數等。請依照上述資料，回答下列第 5 題 至第 8 題。","round":"第二次","topic":"研究設計 > 研究架構圖","answer":"D","exp_raw":"","exp_why":"(D)錯誤：研究架構圖中『無關係』通常是『不畫線』——畫了沒有箭頭的線並不代表兩變項沒有關係。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"架構圖:單箭頭＝因果;雙箭頭＝相關;無關係＝不畫線。","keywords":"研究架構圖, 變項關係箭頭","mnemonic":"研究架構圖:單箭頭因果/雙箭頭相關/無關不畫線。","question":"有關研究架構圖的敘述，下列何者錯誤？","extension":"研究設計(研究架構圖)。","exp_others":"(A)自變項在左、依變項在右、(B)單向箭頭表因果(起點因→終點果)、(C)雙向箭頭表相關——皆正確。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"107110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-107-2-05","law":"","qno":"5","year":"107","major":"抽樣","opt_a":"叢集抽樣法（cluster sampling）","opt_b":"簡單隨機抽樣法（simple random sampling）","opt_c":"便利抽樣法（convenience sampling）","opt_d":"配額抽樣法（quota sampling）","round":"第二次","topic":"抽樣 > 叢集抽樣","answer":"A","exp_raw":"","exp_why":"以「群(如班級/學校)為單位」整群抽取——這是叢集抽樣;(A)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"叢集抽樣=先抽「群」,再對群內全部(或再抽)調查,省成本。","keywords":"叢集抽樣cluster, 學校班級","mnemonic":"叢集抽樣=以群(班級/學校)為單位整群抽取。","question":"此研究的抽樣方法為：","extension":"抽樣;叢集抽樣。","exp_others":"(B)簡單隨機抽個別元素、(C)便利抽樣隨手取、(D)配額抽樣按比例挑——皆非「整群抽取」。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"107110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-107-2-06","law":"","qno":"6","year":"107","major":"研究設計","opt_a":"學校","opt_b":"班級","opt_c":"個人","opt_d":"睡眠品質分數","round":"第二次","topic":"研究設計 > 分析單位","answer":"C","exp_raw":"","exp_why":"研究每位學生的睡眠品質——分析單位是個人;(C)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"分析單位=「資料蒐集與結論的對象層次」;本題是個別學生。","keywords":"分析單位, 個人, 學生","mnemonic":"分析單位=個人(測量每位學生)。","question":"研究的分析單位是：","extension":"研究設計;分析單位。","exp_others":"(A)學校、(B)班級是更高層次、(D)睡眠品質分數是「變項」非分析單位——皆不符。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"107110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-107-2-07","law":"","qno":"7","year":"107","major":"統計檢定","opt_a":"「每天上網時數」與「睡眠品質」具有因果關係，兩者間的因果關係達統計上的顯著","opt_b":"「每天上網時數」與「睡眠品質」，兩者相關達統計上的顯著","opt_c":"「每天上網時數」和「睡眠品質」，沒有顯著相關","opt_d":"「每天上網時數」可以解釋「睡眠品質」64%的變異量","round":"第二次","topic":"統計概念 > 相關係數判讀","answer":"B","exp_raw":"","exp_why":"(B)正確：r＝0.64、p＝.002＜α=.05——兩者『相關』達統計上的顯著。","mistake":"計算邏輯錯誤","subject":"社會工作研究方法","exp_trap":"顯著相關≠因果;解釋變異要把r『平方』。","keywords":"pearson r=0.64, 統計顯著, 因果","mnemonic":"p<α＝顯著相關(非因果);解釋變異＝r的平方(0.64²≈41%)。","question":"研究發現，「每天上網時數」與「睡眠品質」的相關係數 pearson r = 0.64（p=.002）。若顯 著水準α=0.05，以下敘述何者正確？","extension":"統計概念(相關顯著性)。","exp_others":"(A)相關顯著『不能』推因果關係;(C)p=.002是顯著(非不顯著);(D)解釋變異＝r平方＝0.64的平方≈41%(不是64%)。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"107110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-107-2-08","law":"","qno":"8","year":"107","major":"變項","opt_a":"僅①④","opt_b":"僅②③","opt_c":"①②④","opt_d":"②③④","round":"第二次","topic":"變項關係 > 中介變項辨識","answer":"B","exp_raw":"","exp_why":"(B)僅②③：②每週運動時數與睡眠品質有關(運動越多睡眠越佳)③性別與睡眠品質的關係是『透過運動時數』(控制後性別作用消失)。","mistake":"概念混淆","subject":"社會工作研究方法","exp_trap":"控制中介(運動)後原關係消失＝原關係由中介傳遞。","keywords":"控制變項, 中介效應, 運動時數","mnemonic":"第三變項Z的角色:中介變項(X→Z→Y,控制Z後X-Y直接關係消失＝完全中介)、調節變項(Z改變X→Y的影響強度,檢驗X×Z交互作用項對Y的效果;好的支持系統使壓力影響降低＝調節/緩衝)、前導變項(共同原因→虛假關係:控制Z後X-Y關係消失且Z為共因)、控制變項;內衍變項是模型內被解釋的變項(非第三變項屬性)。","question":"研究也發現，單就性別進行比較，女學生的睡眠品質顯著比男學生差，但控制了每週運動時 數後發現，運動時數越高睡眠品質顯著越佳，同時性別就沒有顯著作用了。下列敘述何者正 確？①性別跟睡眠品質有因果關係 ②每週運動時數跟睡眠品質有因果關係 ③性別跟睡眠 品質是虛假關係 ④每週運動時數跟睡眠品質是間接關係","extension":"變項關係(中介解讀)。","exp_others":"①性別與睡眠品質『沒有』直接因果(控制運動後消失);④的敘述不成立。","legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=107110&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"ready","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"107110","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null}]$before$::jsonb;
 expected_after jsonb := $after$[{"id":"R-105-2-12","law":null,"qno":"12","year":"105","major":null,"opt_a":"C. Das, M. E. Kondrat, C. M. Lam, and L. S. Shulman","opt_b":"Chatili Das, Mary Ellen Kondrat, Ching Man Lam, Lee S. Shulman","opt_c":"Das, C., Kondrat, M. E., Lam, C. M., and Shulman, L. S.","opt_d":"Chatili, D., Mary, E. K., Ching, M. L., and Lee, S. S.","round":"第二次","topic":null,"answer":"C","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"某社工人員在撰寫有關課後照顧的評估報告時，參考了一篇由 Chatili Das、Mary Ellen Kondrat、Ching Man Lam、Lee S. Shulman四位作者所共同撰寫的文章。依 APA 格式，在此評估報告的「參考文獻」中，這篇文獻作者的寫法應該是：","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-13","law":null,"qno":"13","year":"105","major":null,"opt_a":"問題型","opt_b":"宣示型","opt_c":"概念型","opt_d":"虛無型","round":"第二次","topic":null,"answer":"B","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"情況：假想廖教授計劃以臺灣社會工作專業人員協會的所有會員進行普查。研究者所擬定的其中一個研究假設為「女性社工人員的倫理兩難決斷力較男性來得高」。請依上述資料回答下列第13題至第16題。\n\n以上說明是屬於那一種研究假設？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_comp