nonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-16","law":null,"qno":"16","year":"105","major":null,"opt_a":"鑑別度（discrimination）","opt_b":"效度（validity）","opt_c":"信度（reliability）","opt_d":"精確度（precision）","round":"第二次","topic":null,"answer":"B","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"情況：假想廖教授計劃以臺灣社會工作專業人員協會的所有會員進行普查。研究者所擬定的其中一個研究假設為「女性社工人員的倫理兩難決斷力較男性來得高」。請依上述資料回答下列第13題至第16題。\n\n若廖教授完成資料分析後，驗證了其所提出的「女性社工人員的倫理兩難決斷力較男性 來得高」這個研究假設。但有不少男性社工人員質疑量表中將進行倫理決策的頻率、時 間及影響人數等題目納入，忽略了男性社工人員比較少有機會從事第一線的實務工作， 因而較少參與在倫理兩難的決策中。請問這些男性社工人員質疑的是這個量表的：","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-20","law":null,"qno":"20","year":"105","major":null,"opt_a":"回收率通常會很低","opt_b":"樣本代表性不足","opt_c":"作答者會相互影響","opt_d":"樣本數經常會不足","round":"第二次","topic":null,"answer":"B","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"從抽樣的理論來看，方便抽樣（convenience sampling）最大的缺點在於：","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=107&code=105090&q=1&s=0606&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-21","law":null,"qno":"21","year":"105","major":null,"opt_a":"樣本數不變，修改問卷內容，使題意更淺顯易懂","opt_b":"樣本數不變，改採分層隨機抽樣進行抽樣，以增加樣本代表性","opt_c":"增加有效樣本數到 10,500 人","opt_d":"針對同樣的樣本改採面訪，以減少電話訪問的機構效應","round":"第二次","topic":null,"answer":"C","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"情況：假想某政府單位委託民間民意調查機構，以電腦隨機撥號的方式，進行「臺灣應否逐步廢除死刑以符合國際人權公約的準則」之電話民調。該調查指稱有效樣本數為3,757份，具有95%的信賴水準（confidence level）。請依上述資料回答下列第21題至第22題。\n\n若該民調想更精準地掌握民意，希望達到 99%的信賴水準，請問該民調公司該怎麼做？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null},{"id":"R-105-2-22","law":null,"qno":"22","year":"105","major":null,"opt_a":"歷史（history）","opt_b":"選取（selection）","opt_c":"成熟（maturation）","opt_d":"統計迴歸（statistical regression）","round":"第二次","topic":null,"answer":"A","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作研究方法","exp_trap":null,"keywords":null,"mnemonic":null,"question":"情況：假想某政府單位委託民間民意調查機構，以電腦隨機撥號的方式，進行「臺灣應否逐步廢除死刑以符合國際人權公約的準則」之電話民調。該調查指稱有效樣本數為3,757份，具有95%的信賴水準（confidence level）。請依上述資料回答下列第21題至第22題。\n\n若在調查前幾天，剛好發生街頭隨機殺人事件，且經媒體大幅報導；顯然此街頭隨機殺 人事件及其後續的討論可能會影響民意調查的結果。請問影響該民意調查效度的因素為 何？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105090&c=107&s=0606&q=1","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"review","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"105090","analysis_attempts":0,"analysis_started