 IF actual IS DISTINCT FROM expected_before THEN RAISE EXCEPTION 'shared correction preimage mismatch'; END IF;
 IF (SELECT count(*) FROM public.questions)<>4800 THEN RAISE EXCEPTION 'corpus count drift'; END IF;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO others FROM public.questions q WHERE id NOT IN ('R-105-2-12','R-105-2-13','R-105-2-14','R-105-2-15','R-105-2-16','R-105-2-20','R-105-2-21','R-105-2-22','R-107-2-04','R-107-2-05','R-107-2-06','R-107-2-07','R-107-2-08');
 SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading FROM public.questions;
