  UPDATE public.questions SET question='情況：假想廖教授計劃以臺灣社會工作專業人員協會的所有會員進行普查。研究者所擬定的其中一個研究假設為「女性社工人員的倫理兩難決斷力較男性來得高」。請依上述資料回答下列第13題至第16題。

若廖教授以其自行設計的 10 題五等尺度量表來測量社工人員的「倫理決斷能力」，得 分越高代表倫理兩難決斷力越高。若研究者想驗證其所提出的這個研究假設，在不改變 變項測量層次的情形下，這位研究者應選用下列那個統計程序？' WHERE id='R-105-2-15';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：假想廖教授計劃以臺灣社會工作專業人員協會的所有會員進行普查。研究者所擬定的其中一個研究假設為「女性社工人員的倫理兩難決斷力較男性來得高」。請依上述資料回答下列第13題至第16題。

若廖教授完成資料分析後，驗證了其所提出的「女性社工人員的倫理兩難決斷力較男性 來得高」這個研究假設。但有不少男性社工人員質疑量表中將進行倫理決策的頻率、時 間及影響人數等題目納入，忽略了男性社工人員比較少有機會從事第一線的實務工作， 因而較少參與在倫理兩難的決策中。請問這些男性社工人員質疑的是這個量表的：' WHERE id='R-105-2-16';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET opt_d='樣本數經常會不足',question='從抽樣的理論來看，方便抽樣（convenience sampling）最大的缺點在於：' WHERE id='R-105-2-20';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：假想某政府單位委託民間民意調查機構，以電腦隨機撥號的方式，進行「臺灣應否逐步廢除死刑以符合國際人權公約的準則」之電話民調。該調查指稱有效樣本數為3,757份，具有95%的信賴水準（confidence level）。請依上述資料回答下列第21題至第22題。

若該民調想更精準地掌握民意，希望達到 99%的信賴水準，請問該民調公司該怎麼做？' WHERE id='R-105-2-21';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：假想某政府單位委託民間民意調查機構，以電腦隨機撥號的方式，進行「臺灣應否逐步廢除死刑以符合國際人權公約的準則」之電話民調。該調查指稱有效樣本數為3,757份，具有95%的信賴水準（confidence level）。請依上述資料回答下列第21題至第22題。

若在調查前幾天，剛好發生街頭隨機殺人事件，且經媒體大幅報導；顯然此街頭隨機殺 人事件及其後續的討論可能會影響民意調查的結果。請問影響該民意調查效度的因素為 何？' WHERE id='R-105-2-22';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET opt_d='沒有箭頭的線條表示兩端的變項沒有關係' WHERE id='R-107-2-04';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：睡眠對健康至關重要。但研究發現，多數大學生睡眠品質不佳。葉教授想了解影響大學生睡眠品質的因素，他從自己任教的大學裡，以系級名單隨機抽取20個班級，到這些班級發放問卷，請全班同學填寫。問卷中，睡眠品質以「匹茲堡睡眠品質量表」（是由7題，每題4點尺度的李克特（Likert）量表所構成，分數越高代表睡眠品質越差）來測量，其他變項包括受訪者性別、每週運動時數、每天上網時數等。請依照上述資料，回答下列第5題至第8題。

此研究的抽樣方法為：' WHERE id='R-107-2-05';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：睡眠對健康至關重要。但研究發現，多數大學生睡眠品質不佳。葉教授想了解影響大學生睡眠品質的因素，他從自己任教的大學裡，以系級名單隨機抽取20個班級，到這些班級發放問卷，請全班同學填寫。問卷中，睡眠品質以「匹茲堡睡眠品質量表」（是由7題，每題4點尺度的李克特（Likert）量表所構成，分數越高代表睡眠品質越差）來測量，其他變項包括受訪者性別、每週運動時數、每天上網時數等。請依照上述資料，回答下列第5題至第8題。

研究的分析單位是：' WHERE id='R-107-2-06';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：睡眠對健康至關重要。但研究發現，多數大學生睡眠品質不佳。葉教授想了解影響大學生睡眠品質的因素，他從自己任教的大學裡，以系級名單隨機抽取20個班級，到這些班級發放問卷，請全班同學填寫。問卷中，睡眠品質以「匹茲堡睡眠品質量表」（是由7題，每題4點尺度的李克特（Likert）量表所構成，分數越高代表睡眠品質越差）來測量，其他變項包括受訪者性別、每週運動時數、每天上網時數等。請依照上述資料，回答下列第5題至第8題。

研究發現，「每天上網時數」與「睡眠品質」的相關係數 pearson r = 0.64（p=.002）。若顯 著水準α=0.05，以下敘述何者正確？' WHERE id='R-107-2-07';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
  UPDATE public.questions SET question='情況：睡眠對健康至關重要。但研究發現，多數大學生睡眠品質不佳。葉教授想了解影響大學生睡眠品質的因素，他從自己任教的大學裡，以系級名單隨機抽取20個班級，到這些班級發放問卷，請全班同學填寫。問卷中，睡眠品質以「匹茲堡睡眠品質量表」（是由7題，每題4點尺度的李克特（Likert）量表所構成，分數越高代表睡眠品質越差）來測量，其他變項包括受訪者性別、每週運動時數、每天上網時數等。請依照上述資料，回答下列第5題至第8題。

研究也發現，單就性別進行比較，女學生的睡眠品質顯著比男學生差，但控制了每週運動時 數後發現，運動時數越高睡眠品質顯著越佳，同時性別就沒有顯著作用了。下列敘述何者正 確？①性別跟睡眠品質有因果關係 ②每週運動時數跟睡眠品質有因果關係 ③性別跟睡眠 品質是虛假關係 ④每週運動時數跟睡眠品質是間接關係' WHERE id='R-107-2-08';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'unexpected affected rows'; END IF;
 UPDATE public.questions SET analysis_status='review' WHERE id IN ('R-105-2-12','R-105-2-13','R-105-2-14','R-105-2-15','R-105-2-16','R-105-2-20','R-105-2-21','R-105-2-22','R-107-2-04','R-107-2-05','R-107-2-06','R-107-2-07','R-107-2-08') AND analysis_status='pending';
 GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>13 THEN RAISE EXCEPTION 'quarantine count mismatch'; END IF;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO actual FROM public.questions q WHERE id IN ('R-105-2-12','R-105-2-13','R-105-2-14','R-105-2-15','R-105-2-16','R-105-2-20','R-105-2-21','R-105-2-22','R-107-2-04','R-107-2-05','R-107-2-06','R-107-2-07','R-107-2-08');
 IF actual IS DISTINCT FROM expected_after THEN RAISE EXCEPTION 'shared correction postimage mismatch'; END IF;
 IF others IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(q) ORDER BY id) FROM public.questions q WHERE id NOT IN ('R-105-2-12','R-105-2-13','R-105-2-14','R-105-2-15','R-105-2-16','R-105-2-20','R-105-2-21','R-105-2-22','R-107-2-04','R-107-2-05','R-107-2-06','R-107-2-07','R-107-2-08')) THEN RAISE EXCEPTION 'unrelated rows changed'; END IF;
 IF grading IS DISTINCT FROM (SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) FROM public.questions) THEN RAISE EXCEPTION 'grading changed'; END IF;
 IF cfg IS DISTINCT FROM (SELECT to_jsonb(c) FROM public.ai_analysis_job_config c WHERE id=true) THEN RAISE EXCEPTION 'analyzer configuration changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.questions WHERE analysis_status='pending') THEN RAISE EXCEPTION 'unexpected pending analysis'; END IF;
 RAISE NOTICE 'SWSI 13-row source correction verified; other4787 and all4800grading unchanged; zero pending';
END $swsi_shared_fix$;
ROLLBACK;
